// MARK: - Create Focus Group View
struct CreateFocusGroupView: View {
    struct GroupIconOption: Identifiable {
        let symbol: String
        let priority: GroupPriority
        var id: String { symbol }
    }

    enum GroupPriority: String, CaseIterable, Identifiable {
        case information = "Information"
        case important = "Important"
        case critical = "Critical"

        var id: String { rawValue }

        var icon: String {
            switch self {
            case .information:
                return "info.circle.fill"
            case .important:
                return "exclamationmark.triangle.fill"
            case .critical:
                return "exclamationmark.octagon.fill"
            }
        }

        var accentColor: Color {
            switch self {
            case .information:
                return Color.tapticInfoBlue
            case .important:
                return Color.tapticImportantAmber
            case .critical:
                return Color.tapticAlertRed
            }
        }

        static func from(icon: String) -> GroupPriority {
            switch icon {
            case "exclamationmark.octagon.fill", "flame.fill", "figure.walk":
                return .critical
            case "exclamationmark.triangle.fill", "bolt.fill", "star.fill", "heart.fill", "building.2.fill":
                return .important
            case "info.circle.fill", "drop.fill", "cloud.fill", "leaf.fill", "sun.max.fill":
                return .information
            default:
                return .important
            }
        }
    }

